1: /* ==========================================================================
2:    The Sweet Oven - Shared Stylesheet
3:    Loaded AFTER Bootstrap 5.3.3 CDN
4:    ========================================================================== */
5: 
6: /* --------------------------------------------------------------------------
7:    1. CSS Custom Properties (Palette & Typography)
8:    -------------------------------------------------------------------------- */
9: :root {
10:   /* Required Brand Palette */
11:   --color-cream: #FFF8EE;        /* Primary page background */
12:   --color-brown: #4A2C1D;        /* Primary text & dark surfaces */
13:   --color-caramel: #B5601E;      /* Primary buttons & accents */
14:   --color-pink: #F3B6C0;         /* Highlights, tags, subtle accents */
15: 
16:   /* Supporting Accessible Tints & Shades */
17:   --color-caramel-dark: #8F4812; /* Hover state & small text links (>= 4.5:1 on cream) */
18:   --color-pink-soft: #FCE8EC;    /* Soft highlight surface */
19:   --color-surface: #FFFFFF;      /* Card & input background */
20:   --color-border: #DFCBB7;       /* Warm border for cards & dividers */
21:   --color-input-border: #B89D85; /* Higher-contrast border for form inputs */
22:   --color-muted: #6E4F3E;        /* Secondary readable text (>= 6.5:1 on cream/white) */
23: 
24:   /* Typography (Google Fonts with reliable system fallbacks) */
25:   --font-heading: 'Playfair Display', Georgia, 'Times New Roman', serif;
26:   --font-body: 'Nunito', 'Segoe UI', Roboto, Arial, sans-serif;
27: 
28:   /* Radii & Shadows */
29:   --radius-sm: 0.5rem;
30:   --radius-md: 0.875rem;
31:   --radius-lg: 1.25rem;
32:   --shadow-soft: 0 4px 14px rgba(74, 44, 29, 0.08);
33:   --shadow-hover: 0 8px 22px rgba(74, 44, 29, 0.14);
34: 
35:   /* Align Bootstrap 5 CSS variables with our theme */
36:   --bs-body-bg: var(--color-cream);
37:   --bs-body-color: var(--color-brown);
38:   --bs-body-font-family: var(--font-body);
39:   --bs-primary: var(--color-caramel);
40:   --bs-primary-rgb: 181, 96, 30;
41:   --bs-link-color: var(--color-caramel-dark);
42:   --bs-link-hover-color: var(--color-brown);
43:   --bs-border-color: var(--color-border);
44: }
45: 
46: /* --------------------------------------------------------------------------
47:    2. Base Layout & Typography
48:    -------------------------------------------------------------------------- */
49: body {
50:   background-color: var(--color-cream);
51:   color: var(--color-brown);
52:   font-family: var(--font-body);
53:   line-height: 1.6;
54:   min-height: 100vh;
55:   display: flex;
56:   flex-direction: column;
57: }
58: 
59: main {
60:   flex: 1 0 auto;
61: }
62: 
63: h1, h2, h3, h4, h5, h6,
64: .font-heading {
65:   font-family: var(--font-heading);
66:   color: var(--color-brown);
67:   font-weight: 700;
68:   line-height: 1.25;
69: }
70: 
71: a {
72:   color: var(--color-caramel-dark);
73:   text-underline-offset: 0.2em;
74: }
75: 
76: a:hover {
77:   color: var(--color-brown);
78: }
79: 
80: .text-muted-bakery {
81:   color: var(--color-muted);
82: }
83: 
84: /* Accessibility: Skip to main content link */
85: .skip-link {
86:   position: absolute;
87:   top: -100px;
88:   left: 1rem;
89:   z-index: 1100;
90:   background-color: var(--color-brown);
91:   color: var(--color-cream);
92:   padding: 0.6rem 1rem;
93:   border-radius: var(--radius-sm);
94:   font-weight: 700;
95:   text-decoration: none;
96: }
97: 
98: .skip-link:focus {
99:   top: 1rem;
100:   color: var(--color-cream);
101: }
102: 
103: /* --------------------------------------------------------------------------
104:    3. Visible Focus States (Keyboard Accessibility)
105:    -------------------------------------------------------------------------- */
106: a:focus-visible,
107: button:focus-visible,
108: input:focus-visible,
109: select:focus-visible,
110: textarea:focus-visible,
111: .btn:focus-visible,
112: .nav-link:focus-visible,
113: .navbar-toggler:focus-visible {
114:   outline: 3px solid var(--color-caramel);
115:   outline-offset: 2px;
116:   box-shadow: 0 0 0 4px rgba(243, 182, 192, 0.55);
117: }
118: 
119: /* --------------------------------------------------------------------------
120:    4. Shared Header & Navbar
121:    -------------------------------------------------------------------------- */
122: .site-header {
123:   background-color: var(--color-surface);
124:   border-bottom: 3px solid var(--color-pink);
125:   box-shadow: 0 2px 10px rgba(74, 44, 29, 0.06);
126: }
127: 
128: .site-header .navbar-brand {
129:   display: inline-flex;
130:   align-items: center;
131:   gap: 0.65rem;
132:   color: var(--color-brown);
133:   font-family: var(--font-heading);
134:   font-size: 1.4rem;
135:   font-weight: 700;
136:   text-decoration: none;
137: }
138: 
139: .site-header .navbar-brand:hover {
140:   color: var(--color-caramel-dark);
141: }
142: 
143: .brand-logo {
144:   width: 42px;
145:   height: 42px;
146:   flex-shrink: 0;
147: }
148: 
149: .site-header .nav-link {
150:   color: var(--color-brown);
151:   font-weight: 700;
152:   padding: 0.5rem 0.9rem;
153:   border-radius: var(--radius-sm);
154:   transition: background-color 0.2s ease, color 0.2s ease;
155: }
156: 
157: .site-header .nav-link:hover {
158:   background-color: var(--color-pink-soft);
159:   color: var(--color-brown);
160: }
161: 
162: .site-header .nav-link.active,
163: .site-header .nav-link[aria-current="page"] {
164:   background-color: var(--color-pink);
165:   color: var(--color-brown);
166: }
167: 
168: /* Highlight Cart button in navbar while keeping high contrast */
169: .site-header .nav-link-cart {
170:   background-color: var(--color-caramel);
171:   color: #FFFFFF;
172: }
173: 
174: .site-header .nav-link-cart:hover,
175: .site-header .nav-link-cart.active,
176: .site-header .nav-link-cart[aria-current="page"] {
177:   background-color: var(--color-caramel-dark);
178:   color: #FFFFFF;
179: }
180: 
181: /* Mobile hamburger button styling */
182: .site-header .navbar-toggler {
183:   border: 2px solid var(--color-brown);
184:   padding: 0.4rem 0.65rem;
185:   color: var(--color-brown);
186: }
187: 
188: .site-header .navbar-toggler-icon {
189:   background-image: url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 30 30'%3e%3cpath stroke='%234A2C1D' stroke-linecap='round' stroke-miterlimit='10' stroke-width='2.4' d='M4 7h22M4 15h22M4 23h22'/%3e%3c/svg%3e");
190: }
191: 
192: /* --------------------------------------------------------------------------
193:    5. Buttons
194:    -------------------------------------------------------------------------- */
195: .btn {
196:   font-weight: 700;
197:   border-radius: var(--radius-sm);
198:   padding: 0.55rem 1.2rem;
199:   transition: background-color 0.2s ease, border-color 0.2s ease, transform 0.15s ease;
200: }
201: 
202: /* Caramel primary button (white on #B5601E = 4.51:1 WCAG AA contrast) */
203: .btn-bakery,
204: .btn-primary {
205:   background-color: var(--color-caramel);
206:   border-color: var(--color-caramel);
207:   color: #FFFFFF;
208: }
209: 
210: .btn-bakery:hover,
211: .btn-bakery:active,
212: .btn-primary:hover,
213: .btn-primary:active,
214: .btn-primary:focus {
215:   background-color: var(--color-caramel-dark);
216:   border-color: var(--color-caramel-dark);
217:   color: #FFFFFF;
218: }
219: 
220: /* Outline caramel/brown button with pink highlight hover */
221: .btn-outline-bakery {
222:   background-color: transparent;
223:   border: 2px solid var(--color-caramel);
224:   color: var(--color-brown);
225: }
226: 
227: .btn-outline-bakery:hover,
228: .btn-outline-bakery:active {
229:   background-color: var(--color-pink);
230:   border-color: var(--color-brown);
231:   color: var(--color-brown);
232: }
233: 
234: /* Pink highlight button with dark brown text (7.38:1 contrast) */
235: .btn-pink {
236:   background-color: var(--color-pink);
237:   border-color: var(--color-pink);
238:   color: var(--color-brown);
239: }
240: 
241: .btn-pink:hover,
242: .btn-pink:active {
243:   background-color: #EAA0AD;
244:   border-color: var(--color-brown);
245:   color: var(--color-brown);
246: }
247: 
248: /* --------------------------------------------------------------------------
249:    6. Cards & Highlight Badges
250:    -------------------------------------------------------------------------- */
251: .card,
252: .bakery-card {
253:   background-color: var(--color-surface);
254:   border: 1px solid var(--color-border);
255:   border-radius: var(--radius-md);
256:   box-shadow: var(--shadow-soft);
257:   color: var(--color-brown);
258:   transition: transform 0.2s ease, box-shadow 0.2s ease;
259: }
260: 
261: .card-hover:hover {
262:   transform: translateY(-3px);
263:   box-shadow: var(--shadow-hover);
264: }
265: 
266: .card-header {
267:   background-color: var(--color-pink-soft);
268:   border-bottom: 1px solid var(--color-border);
269:   color: var(--color-brown);
270:   font-weight: 700;
271: }
272: 
273: .badge-pink,
274: .highlight-pink {
275:   background-color: var(--color-pink);
276:   color: var(--color-brown);
277:   font-weight: 700;
278: }
279: 
280: .section-highlight {
281:   background-color: var(--color-pink-soft);
282:   border: 1px solid var(--color-pink);
283:   border-radius: var(--radius-lg);
284: }
285: 
286: /* --------------------------------------------------------------------------
287:    7. Form Inputs & Labels
288:    -------------------------------------------------------------------------- */
289: .form-label {
290:   color: var(--color-brown);
291:   font-weight: 700;
292:   margin-bottom: 0.35rem;
293: }
294: 
295: .form-control,
296: .form-select {
297:   background-color: var(--color-surface);
298:   color: var(--color-brown);
299:   border: 1.5px solid var(--color-input-border);
300:   border-radius: var(--radius-sm);
301:   padding: 0.55rem 0.85rem;
302: }
303: 
304: .form-control::placeholder {
305:   color: var(--color-muted);
306:   opacity: 0.85;
307: }
308: 
309: .form-control:focus,
310: .form-select:focus {
311:   background-color: var(--color-surface);
312:   color: var(--color-brown);
313:   border-color: var(--color-caramel);
314:   box-shadow: 0 0 0 0.25rem rgba(181, 96, 30, 0.25);
315: }
316: 
317: .form-check-input {
318:   border: 1.5px solid var(--color-brown);
319: }
320: 
321: .form-check-input:checked {
322:   background-color: var(--color-caramel);
323:   border-color: var(--color-caramel);
324: }
325: 
326: /* --------------------------------------------------------------------------
327:    8. Shared Footer
328:    -------------------------------------------------------------------------- */
329: .site-footer {
330:   background-color: var(--color-brown);
331:   color: var(--color-cream);
332:   border-top: 4px solid var(--color-caramel);
333: }
334: 
335: .site-footer h2,
336: .site-footer h3,
337: .site-footer .footer-heading {
338:   font-family: var(--font-heading);
339:   color: var(--color-pink);
340:   font-size: 1.15rem;
341:   font-weight: 700;
342:   margin-bottom: 0.75rem;
343: }
344: 
345: .site-footer a {
346:   color: var(--color-cream);
347:   text-decoration: none;
348: }
349: 
350: .site-footer a:hover {
351:   color: var(--color-pink);
352:   text-decoration: underline;
353: }
354: 
355: .site-footer a:focus-visible {
356:   outline: 3px solid var(--color-pink);
357:   outline-offset: 2px;
358:   box-shadow: none;
359: }
360: 
361: .site-footer .footer-divider {
362:   border-color: rgba(255, 248, 238, 0.2);
363: }
364: 
365: .site-footer .footer-copyright {
366:   color: var(--color-cream);
367:   opacity: 0.9;
368: }

