  border-color: var(--color-caramel);
}

.category-pill.is-active {
  background-color: var(--color-caramel);
  border-color: var(--color-caramel);
  color: #FFFFFF;
}

.dietary-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
