  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 0.42rem 0.7rem;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  user-select: none;
}

.dietary-chip input {
  margin-top: 0;
  cursor: pointer;
}

.menu-card {
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.menu-card-media {
  position: relative;
  background-color: var(--color-cream);
  border-bottom: 1px solid var(--color-border);
  padding: 0.75rem;
  text-align: center;
}

.menu-card-img {
  width: 100%;
  max-height: 185px;
  object-fit: contain;
  display: block;
  margin: 0 auto;
}

.menu-card-badge {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  background-color: var(--color-pink);
  color: var(--color-brown);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.25rem 0.65rem;
  border-radius: 999px;
  border: 1px solid rgba(74, 44, 29, 0.12);
}

.favorite-toggle-btn {
  position: absolute;
  top: 0.75rem;
  right: 0.75rem;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1.5px solid var(--color-border);
  background-color: var(--color-surface);
  color: var(--color-brown);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  line-height: 1;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.15s ease, border-color 0.2s ease;
}

.favorite-toggle-btn:hover {
